<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Privacy;use Acorn\SafetyHealthcheck\Database\Schema;final class ExportEraser{public function register():void{add_filter('wp_privacy_personal_data_exporters',fn($e)=>$e+['acorn-healthcheck'=>['exporter_friendly_name'=>'Acorn Healthcheck','callback'=>[$this,'export']]]);add_filter('wp_privacy_personal_data_erasers',fn($e)=>$e+['acorn-healthcheck'=>['eraser_friendly_name'=>'Acorn Healthcheck','callback'=>[$this,'erase']]]);}public function export(string$email):array{return['data'=>[],'done'=>true];}public function erase(string$email):array{global$wpdb;$wpdb->update(Schema::table('contacts'),['first_name'=>'Removed following privacy request','last_name'=>'','email'=>'','telephone'=>'','postcode'=>''],['email'=>$email]);return['items_removed'=>true,'items_retained'=>false,'messages'=>[],'done'=>true];}}
